def attack_detection():
    st.markdown(
        """
        <style>
        .main {
            background-image: url("data:image/jpg;base64,");
            background-size: cover;
            background-position: center;
            background-repeat: no-repeat;
            background-color: rgba(255, 255, 255, 0.6);
            background-blend-mode: overlay;
        }

        .prevention-list {
            margin-left: 1rem;
        }
        .prevention-item {
            margin-bottom: 1rem;
            padding-left: 1.5rem;
            text-indent: -1.5rem;
        }
        div{
            color: black;
        }
        </style>
        """,
        unsafe_allow_html=True
    )

    st.markdown('<div class="detection-container">', unsafe_allow_html=True)

    # Upload section
    with st.container():
        st.markdown('<div class="upload-box">', unsafe_allow_html=True)
        col1, col2, col3 = st.columns([1, 5, 1])
        file = col2.file_uploader("Upload EEG Data (CSV)", type=["csv"], 
                                 help="Please upload a CSV file containing EEG readings with the correct format")
        st.markdown('</div>', unsafe_allow_html=True)

    if file is not None:
        try:
            # Data processing and prediction
            with st.spinner('Analyzing EEG data...'):
                data = pd.read_csv(file)
                
                # Show data preview
                with st.expander("View Uploaded Data"):
                    st.dataframe(data.head())
                
                # Make prediction
                data_reshaped = preprocess_data(data, scaler)
                prediction = model.predict(data_reshaped)
                prediction_class = (prediction > 0.5).astype(int)
                result = "Epileptic seizure" if prediction_class[0][0] == 1 else "Healthy"

                # Display results
                st.markdown('<div class="result-box">', unsafe_allow_html=True)
                
                if result == "Epileptic seizure":
                    st.error("⚠ *Prediction:* Epileptic seizure detected")
                    
                    if st.session_state.role == 'user':
                        st.markdown("""
                        <div style="margin-top: 1.5rem;">
                            <h4 style="color: black;">Prevention Measures</h4>
                            <div class="prevention-list">
                                <div class="prevention-item">1. <b>Avoid triggers:</b> Identify and avoid potential triggers that may lead to seizures, such as stress, lack of sleep, or certain foods.</div>
                                <div class="prevention-item">2. <b>Medication:</b> Follow your doctor's prescribed medication regimen to manage seizures effectively.</div>
                                <div class="prevention-item">3. <b>Regular check-ups:</b> Schedule regular appointments with your healthcare provider to monitor your condition.</div>
                                <div class="prevention-item">4. <b>Emergency plan:</b> Have a plan in place for what to do in case of a seizure, including notifying someone nearby.</div>
                                <div class="prevention-item">5. <b>Medical alert bracelet:</b> Consider wearing a medical alert bracelet to inform others about your condition in case of an emergency.</div>
                                <div class="prevention-item">6. <b>Lifestyle changes:</b> Maintain a healthy lifestyle, including a balanced diet, regular exercise, and sufficient sleep.</div>
                            </div>
                        </div>
                        """, unsafe_allow_html=True)
                else:
                    st.success("✅ *Prediction:* No seizure activity detected")
                    if st.session_state.role == 'user':
                        st.info("""
                        *Note:* This is a screening tool only. Continue with regular 
                        medical check-ups and consult your doctor for professional advice.
                        """)
                
                st.markdown('</div>', unsafe_allow_html=True)

        except Exception as e:
            st.error(f"Error processing file: {str(e)}")
            st.info("Please ensure your file: \n- Is in CSV format \n- Contains the correct EEG data structure \n- Has all required columns")

    st.markdown('</div>', unsafe_allow_html=True)  # Close container

